def isomorphicString(s, t):
    if len(s) != len(t):
        return False

    s_map = {}
    t_map = {}

    for i in range(len(s)):
        char_s = s[i]
        char_t = t[i]

        if (char_s in s_map and s_map[char_s] != char_t) or \
           (char_t in t_map and t_map[char_t] != char_s):
            return False

        s_map[char_s] = char_t
        t_map[char_t] = char_s

    return True

